lse;return true}function checkRef(){clearTimeout(timer);const v=f.ref_number.value.trim();if(!v){setRefState('empty','Reference number is required.');valid(0);return}setRefState('checking','Checking reference numberâ€¦');next.disabled=true;timer=setTimeout(async()=>{try{const r=await fetch('archive_check_ref.php?ref='+encodeURIComponent(v),{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('check failed');const j=await r.json();if(j.available){setRefState('available','Reference number is available.');}else{setRefState('taken','Reference number is already taken. Choose another number.');}valid(0)}catch(e){setRefState('error','Reference check is unavailable. Please try again.');valid(0)}},350)}function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function review(){document.getElementById('review-box').innerHTML='<p><strong>Reference No</strong><br>'+esc(f.ref_number.value)+'</p><p><strong>Document</strong><br>'+esc(f.document_1.files[0]?.name||'None')+'</p><p><strong>Sender</strong><br>'+esc(f.sender_name.value)+' Ã‚Â· '+esc(f.sender_phone.value)+'</p><p><strong>Amount</strong><br>'+esc('<?=e(CURRENCY)?>'+Number(f.amount.value).toFixed(2))+'</p>'}function show(n){i=Math.max(0,Math.min(3,n));steps.forEach((s,k)=>s.classList.toggle('active',k===i));title.textContent=labels[i][0];instruction.textContent=labels[i][1];meta.textContent=`Step ${i+1} of 4 - ${labels[i][0]}`;bar.style.width=((i+1)*25)+'%';back.hidden=i===0;next.hidden=i===3;save.hidden=i!==3;if(i===3)review();else valid(i);activity();window.scrollTo({top:0,behavior:'smooth'})}f.ref_number.addEventListener('input',checkRef);f.querySelectorAll('input').forEach(x=>x.addEventListener('input',()=>{activity();if(i<3&&x!==f.ref_number)valid(i)}));f.document_1.addEventListener('change',()=>{activity();valid(1)});next.onclick=()=>{if(valid(i))show(i+1)};back.onclick=()=>show(i-1);f.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.targ